{
  "width": 900,
  "height": 110,
  "controls": [
    {
      "type": "select",
      "label": "Reverse",
      "bind": "ll_reverse",
      "default": "careful",
      "options": [
        {
          "label": "Careful: remember next, then flip",
          "value": "careful"
        },
        {
          "label": "Careless: flip, then remember next",
          "value": "flip_first"
        }
      ],
      "x": 0,
      "y": 0,
      "width": 460,
      "height": 76
    }
  ]
}

#include <stdio.h>
#include <string.h>
#include <nb.h>

/* A linked list in a node pool: a "pointer" is an index, -1 is NULL. */
int val[32];
int nxt[32];
int used = 0;
int head = -1;

/* The pointer variables shown in the picture (-2 = not in use right now). */
int v_prev = -2, v_cur = -2, v_next = -2;

/* Every change is recorded as a frame of the __NB_SET__ line. */
const char *op = "";
int frames = 0;
char say[160];

void frame(void) {
    printf(frames++ ? ",{" : "{");
    printf("\"op\":\"%s\",\"head\":%d,\"val\":[", op, head);
    for (int i = 0; i < used; i++) printf(i ? ",%d" : "%d", val[i]);
    printf("],\"nxt\":[");
    for (int i = 0; i < used; i++) printf(i ? ",%d" : "%d", nxt[i]);
    printf("],\"prev\":%d,\"cur\":%d,\"next\":%d,\"say\":\"%s\"}", v_prev, v_cur, v_next, say);
}

void clear_vars(void) { v_prev = -2; v_cur = -2; v_next = -2; }

int alloc_node(int v) {
    val[used] = v;
    nxt[used] = -1;
    return used++;
}

void push_back(int v) {
    op = "push_back";
    if (head == -1) {
        head = alloc_node(v);
        snprintf(say, sizeof say, "push_back(%d): the list was empty, so head points at the new node", v);
        frame();
        return;
    }
    int cur = head;
    v_cur = cur;
    snprintf(say, sizeof say, "push_back(%d): start at head and walk to the last node", v);
    frame();
    while (nxt[cur] != -1) {
        cur = nxt[cur];
        v_cur = cur;
        snprintf(say, sizeof say, "push_back(%d): cur steps to %d", v, val[cur]);
        frame();
    }
    nxt[cur] = alloc_node(v);   /* make the node only when there is an arrow to hold it */
    snprintf(say, sizeof say, "push_back(%d): the last node, %d, now points at the new node", v, val[cur]);
    frame();
    clear_vars();
}

void insert_after(int target, int v) {
    op = "insert_after";
    int cur = head;
    v_cur = cur;
    snprintf(say, sizeof say, "insert_after(%d, %d): look for %d", target, v, target);
    frame();
    while (cur != -1 && val[cur] != target) {
        cur = nxt[cur];
        v_cur = cur;
        snprintf(say, sizeof say, "insert_after(%d, %d): cur steps on", target, v);
        frame();
    }
    if (cur == -1) { clear_vars(); return; }
    int n = alloc_node(v);
    v_next = n;
    nxt[n] = nxt[cur];   /* new node adopts the tail... */
    snprintf(say, sizeof say, "the new node %d points where %d pointed", v, target);
    frame();
    nxt[cur] = n;        /* ...then the target adopts the new node */
    snprintf(say, sizeof say, "%d now points at %d: it is in the list", target, v);
    frame();
    clear_vars();
}

void remove_value(int v) {
    op = "remove";
    if (head == -1) return;
    if (val[head] == v) { head = nxt[head]; return; }
    int cur = head;
    v_cur = cur;
    snprintf(say, sizeof say, "remove(%d): look for the node before it", v);
    frame();
    while (nxt[cur] != -1 && val[nxt[cur]] != v) {
        cur = nxt[cur];
        v_cur = cur;
        snprintf(say, sizeof say, "remove(%d): cur steps on", v);
        frame();
    }
    if (nxt[cur] != -1) {
        v_next = nxt[cur];
        snprintf(say, sizeof say, "the node after %d is %d", val[cur], v);
        frame();
        nxt[cur] = nxt[nxt[cur]];
        snprintf(say, sizeof say, "%d now skips over %d: nothing points at it any more", val[cur], v);
        frame();
    }
    clear_vars();
}

/* Reverse in place. The safe order: remember next, flip the arrow, step on. */
void reverse_list(int careful) {
    op = "reverse";
    int prev = -1;
    int cur = head;
    v_prev = prev; v_cur = cur;
    snprintf(say, sizeof say, "reverse: prev starts at NULL, cur at head");
    frame();
    while (cur != -1) {
        int next;
        if (careful) {
            next = nxt[cur];   /* remember where we were going */
            v_next = next;
            snprintf(say, sizeof say, "remember next: the node after %d", val[cur]);
            frame();
            nxt[cur] = prev;   /* flip the arrow */
            snprintf(say, sizeof say, "flip: %d now points back at prev", val[cur]);
            frame();
        } else {
            nxt[cur] = prev;   /* flip the arrow first... */
            snprintf(say, sizeof say, "flip first: %d now points back at prev", val[cur]);
            frame();
            next = nxt[cur];   /* ...so "next" is the node we just pointed back at */
            v_next = next;
            snprintf(say, sizeof say, "remember next: but %d now points back, so next is prev", val[cur]);
            frame();
        }
        prev = cur;
        cur = next;
        v_prev = prev; v_cur = cur;
        snprintf(say, sizeof say, "step on: prev and cur both move one node");
        frame();
    }
    head = prev;
    clear_vars();
    snprintf(say, sizeof say, "head = prev: the list now starts at %d", val[head]);
    frame();
}

void describe(char *buf) {
    int cur = head, n = 0, len = 0;
    buf[0] = 0;
    while (cur != -1 && n < 32) {
        len += snprintf(buf + len, 200 - len, "%d ", val[cur]);
        cur = nxt[cur];
        n++;
    }
}

int main() {
    char mode[32];
    if (nb_get_string("ll_reverse", mode, sizeof mode) < 0) strcpy(mode, "careful");
    int careful = strcmp(mode, "flip_first") != 0;
    char lines[5][200];

    printf("__NB_SET__ {\"key\":\"ll\",\"value\":{\"mode\":\"%s\",\"frames\":[", careful ? "careful" : "flip_first");
    push_back(10); push_back(20); push_back(30); push_back(40);
    describe(lines[0]);
    insert_after(20, 25);
    describe(lines[1]);
    remove_value(30);
    describe(lines[2]);
    reverse_list(careful);
    describe(lines[3]);
    printf("]}}\n");

    printf("initial:   %s\n", lines[0]);
    printf("insert 25: %s\n", lines[1]);
    printf("remove 30: %s\n", lines[2]);
    printf("reversed:  %s(%s reverse)\n", lines[3], careful ? "careful" : "flip-first");
    printf("%d frames recorded, %d nodes in the pool\n", frames, used);
    return 0;
}

// Follow the arrows in every frame and count what the program can still reach.
const ll = nb.get('ll');
if (!ll) return 'Run the C cell first.';

function walk(fr) {
  const order = [], seen = new Set();
  for (let i = fr.head; i !== -1 && !seen.has(i); i = fr.nxt[i]) { seen.add(i); order.push(i); }
  return order;
}
// Everything the program can still get to: from head, or from prev, cur and next.
function reachable(fr) {
  const seen = new Set(walk(fr));
  for (let j of [fr.prev, fr.cur, fr.next]) {
    for (; j >= 0 && !seen.has(j); j = fr.nxt[j]) seen.add(j);
  }
  return seen.size;
}

const rows = [];
ll.frames.forEach((fr, step) => {
  const order = walk(fr);
  rows.push({ step: step + 1, nodes: reachable(fr), series: 'still reachable', op: fr.op });
  rows.push({ step: step + 1, nodes: fr.val.length, series: 'nodes in the pool', op: fr.op });
  const next = ll.frames[step + 1];
  if (!next || next.op !== fr.op) {
    console.log(('after ' + fr.op + ':').padEnd(20) + order.map(i => fr.val[i]).join(' -> ') + ' -> NULL');
  }
});

const end = ll.frames.at(-1);
const final = walk(end).map(i => end.val[i]);
console.log('\nreverse mode: ' + ll.mode);
const least = Math.min(...ll.frames.filter(fr => fr.op === 'reverse').map(reachable));
console.log('fewest nodes reachable during the reverse: ' + least);
console.log('nodes in the pool at the end: ' + end.val.length + ', reachable: ' + final.length);
console.log('lost: ' + (end.val.length - final.length) + ' (one is 30, removed on purpose)');
console.log('final list is 40, 25, 20, 10: ' + (final.join() === '40,25,20,10'));

return {
  $schema: 'https://vega.github.io/schema/vega-lite/v5.json',
  width: 'container',
  height: 240,
  title: 'Nodes the program can still reach, step by step (' + ll.mode + ' reverse)',
  data: { values: rows },
  layer: [
    { mark: { type: 'line', interpolate: 'step-after' },
      encoding: {
        x: { field: 'step', type: 'quantitative' },
        y: { field: 'nodes', type: 'quantitative', title: 'nodes', scale: { domain: [0, 6] } },
        strokeDash: { field: 'series', type: 'nominal', title: null },
        detail: { field: 'series' },
        color: { value: '#94a3b8' },
      } },
    { transform: [{ filter: "datum.series === 'still reachable'" }],
      mark: { type: 'point', filled: true, size: 60 },
      encoding: {
        x: { field: 'step', type: 'quantitative' },
        y: { field: 'nodes', type: 'quantitative' },
        color: { field: 'op', type: 'nominal', title: 'operation', sort: ['push_back', 'insert_after', 'remove', 'reverse'] },
      } },
  ],
};
